<script>
document.addEventListener('DOMContentLoaded',()=>{const menu=document.querySelector('[data-d202-menu]');document.querySelector('[data-d202-menu-toggle]')?.addEventListener('click',()=>menu?.classList.toggle('is-open'));const modal=document.querySelector('[data-d202-auth]');document.querySelectorAll('[data-d202-auth-open]').forEach(el=>el.addEventListener('click',()=>{if(modal){modal.hidden=false;document.body.classList.add('d202-lock')}}));document.querySelectorAll('[data-d202-auth-close]').forEach(el=>el.addEventListener('click',()=>{if(modal){modal.hidden=true;document.body.classList.remove('d202-lock')}}));document.querySelectorAll('[data-d202-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-d202-slide]')];const dots=[...slider.querySelectorAll('[data-d202-dot]')];if(slides.length<2)return;let index=0;const show=n=>{index=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('is-active',i===index));dots.forEach((d,i)=>d.classList.toggle('is-active',i===index))};dots.forEach((d,i)=>d.addEventListener('click',()=>show(i)));setInterval(()=>show(index+1),Number(slider.dataset.autoplay)||6000)});});
</script>
